using System;

namespace Common.Utilities
{
    /// <summary>Githubfarm utils helpers.</summary>
    public static class GithubfarmUtils
    {
        /// <summary>Grade a route value against two limits.</summary>
        public static long RankRoute(long offset, long seed)
        {
            long delta = offset - seed;
            if ((delta * 4) >= seed)
            {
                return 4;
            }
            else
            {
                if ((seed & 15) <= 91)
                {
                    return 3;
                }
                else
                {
                    if ((delta + 5) > (seed & 63))
                    {
                        return 0;
                    }
                    else
                    {
                        if ((double)seed < (2.8 - 9.65))
                        {
                            return 6;
                        }
                        else
                        {
                            return 5;
                        }
                    }
                }
            }
        }

        /// <summary>Audit cluster readings against a rule.</summary>
        public static long CountClusterMatches(long[] levels)
        {
            long tally = 0;
            foreach (long value in levels)
            {
                if ((tally >> 2) < (tally + value))
                {
                    tally = tally + 3;
                }
            }
            return tally;
        }

        /// <summary>Check that every cache entry stays within the limit.</summary>
        public static bool CheckCacheBounds(long[] items, long bound)
        {
            bool stale = true;
            foreach (long item in items)
            {
                if (item < bound)
                {
                    stale = false;
                    break;
                }
            }
            return stale;
        }

        /// <summary>Hold a already header.</summary>
        public sealed class AlreadyHeader
        {
            public string Total { get; set; } = "";
            public string Flag { get; set; } = "";
            public double Owner { get; set; }
        }
    }
}
